import{_ as t,o as e,c as i,a0 as o}from"./chunks/framework.D7EjqxMK.js";const u=JSON.parse('{"title":"成本控制与 FinOps","description":"","frontmatter":{},"headers":[],"relativePath":"07-ai-coding/06_工程实践/05_成本控制与FinOps.md","filePath":"07-ai-coding/06_工程实践/05_成本控制与FinOps.md"}'),n={name:"07-ai-coding/06_工程实践/05_成本控制与FinOps.md"};function l(r,a,s,d,h,c){return e(),i("div",null,[...a[0]||(a[0]=[o(`<h1 id="成本控制与-finops" tabindex="-1">成本控制与 FinOps <a class="header-anchor" href="#成本控制与-finops" aria-label="Permalink to &quot;成本控制与 FinOps&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块六 · 06_工程实践 · 第 5 节 <strong>难度</strong>：⭐⭐</p></blockquote><hr><h2 id="_1-ai-编程成本来源" tabindex="-1">1. AI 编程成本来源 <a class="header-anchor" href="#_1-ai-编程成本来源" aria-label="Permalink to &quot;1. AI 编程成本来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>成本项</th><th>说明</th><th>占比</th></tr></thead><tbody><tr><td>API 调用费</td><td>Cursor/Claude Code 等工具费用</td><td>50-70%</td></tr><tr><td>模型推理费</td><td>按 Token 计费的 LLM API</td><td>20-30%</td></tr><tr><td>基础设施费</td><td>IDE、服务器等</td><td>10-15%</td></tr></tbody></table><hr><h2 id="_2-成本优化策略" tabindex="-1">2. 成本优化策略 <a class="header-anchor" href="#_2-成本优化策略" aria-label="Permalink to &quot;2. 成本优化策略&quot;">​</a></h2><h3 id="策略一-模型分层" tabindex="-1">策略一：模型分层 <a class="header-anchor" href="#策略一-模型分层" aria-label="Permalink to &quot;策略一：模型分层&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>简单任务 → GPT-4o-mini / Claude Haiku ($0.15-0.50/1M tokens)</span></span>
<span class="line"><span>中等任务 → Claude Sonnet / GPT-4o ($3-15/1M tokens)</span></span>
<span class="line"><span>复杂任务 → Claude Opus / GPT-4.5 ($15-60/1M tokens)</span></span></code></pre></div><h3 id="策略二-缓存" tabindex="-1">策略二：缓存 <a class="header-anchor" href="#策略二-缓存" aria-label="Permalink to &quot;策略二：缓存&quot;">​</a></h3><ul><li>使用工具的缓存功能</li><li>重复请求避免重新调用</li><li>减少 Token 消耗</li></ul><h3 id="策略三-减少迭代" tabindex="-1">策略三：减少迭代 <a class="header-anchor" href="#策略三-减少迭代" aria-label="Permalink to &quot;策略三：减少迭代&quot;">​</a></h3><ul><li>写好 PRD，减少反复修改</li><li>用 Spec 驱动，减少 Vibe 式迭代</li></ul><h3 id="策略四-本地模型" tabindex="-1">策略四：本地模型 <a class="header-anchor" href="#策略四-本地模型" aria-label="Permalink to &quot;策略四：本地模型&quot;">​</a></h3><ul><li>对敏感数据使用本地小模型</li><li>减少对 API 的依赖</li></ul><hr><h2 id="_3-成本监控" tabindex="-1">3. 成本监控 <a class="header-anchor" href="#_3-成本监控" aria-label="Permalink to &quot;3. 成本监控&quot;">​</a></h2><ul><li>定期查看 API 使用量</li><li>设置月度预算告警</li><li>分析每任务的 Token 消耗</li><li>识别高成本任务模式</li></ul><hr><h2 id="_4-参考资料" tabindex="-1">4. 参考资料 <a class="header-anchor" href="#_4-参考资料" aria-label="Permalink to &quot;4. 参考资料&quot;">​</a></h2><ul><li><a href="https://callsphere.ai/blog/ai-agent-cost-optimization-strategies-production.md" target="_blank" rel="noreferrer">AI Agent Cost Optimization: Strategies for Keeping Production Costs Under Control</a></li><li><a href="https://zylos.ai/research/2026-04-12-ai-agent-cost-optimization-token-budget-model-routing" target="_blank" rel="noreferrer">AI Agent Cost Optimization: Token Budgets, Model Routing, and Production FinOps (Zylos)</a></li></ul>`,21)])])}const _=t(n,[["render",l]]);export{u as __pageData,_ as default};
